CREATE OR REPLACE PROCEDURE testing123_1_20261117195011()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS CALLER
AS
$$
BEGIN
    BEGIN TRANSACTION;

    MERGE INTO SF_BIGHAMMER.SILVER.DIM_ORACLE_PROGRAMS AS target
    USING (
    WITH RAW_ORACLE_CHARGE_PROGRAM_CDC AS (
        SELECT PROGRAM_ID AS PROGRAM_ID_src_1, COMPANY_ID AS COMPANY_ID_src_1, PROGRAM_NAME AS PROGRAM_NAME_src_1, PROGRAM_DESCRIPTION AS PROGRAM_DESCRIPTION_src_1, TRANSACTION_TYPE AS TRANSACTION_TYPE_src_1, FREQUENCY AS FREQUENCY_src_1, DOC_TYPE AS DOC_TYPE_src_1, EXACT_AMOUNT AS EXACT_AMOUNT_src_1, SCHEDULE_VALIDATION AS SCHEDULE_VALIDATION_src_1, CREATED_DATE AS CREATED_DATE_src_1, CREATED_BY AS CREATED_BY_src_1, MODIFIED_DATE AS MODIFIED_DATE_src_1, MODIFIED_BY AS MODIFIED_BY_src_1, CDC_OPERATION AS CDC_OPERATION_src_1 FROM SF_BIGHAMMER.RAW.RAW_ORACLE_CHARGE_PROGRAM_CDC
    ),
    SOURCE_SYSTEMS AS (
        SELECT SOURCE_SYSTEM_ID AS SOURCE_SYSTEM_ID_src_2, SOURCE_SYSTEM_NAME AS SOURCE_SYSTEM_NAME_src_2, UPDATE_TIMESTAMP AS UPDATE_TIMESTAMP_src_2 FROM SF_BIGHAMMER.SF_BH_METADATA.SOURCE_SYSTEMS
    ),
    TEST_WATERMARK AS (
        SELECT TABLE_NAME AS TABLE_NAME_src_3, LAST_LOAD_TIMESTAMP AS LAST_LOAD_TIMESTAMP_src_3, UPDATE_TIMESTAMP AS UPDATE_TIMESTAMP_src_3, LAST_LOAD_ID AS LAST_LOAD_ID_src_3 FROM SF_BIGHAMMER.SF_BH_METADATA.TEST_WATERMARK
    ),
    FCT_ORDERS_CUST_SS AS (
        SELECT ORDER_ID AS ORDER_ID_src_4, CUSTOMER_ID AS CUSTOMER_ID_src_4, STORE_ID AS STORE_ID_src_4, ORDER_AMOUNT AS ORDER_AMOUNT_src_4, ORDER_STATUS AS ORDER_STATUS_src_4, ORDER_UPDATED_AT AS ORDER_UPDATED_AT_src_4, CREATED_AT AS CREATED_AT_src_4, MODIFIED_AT AS MODIFIED_AT_src_4 FROM SF_BIGHAMMER.SILVER.FCT_ORDERS_CUST_SS
    ),
    DIM_CRM_EXPENSE_TYPES AS (
        SELECT EXPENSE_TYPE_ID AS EXPENSE_TYPE_ID_src_5, EXPENSE_TYPE_DESCRIPTION AS EXPENSE_TYPE_DESCRIPTION_src_5, SRC_CREATED_AT AS SRC_CREATED_AT_src_5, SRC_MODIFIED_AT AS SRC_MODIFIED_AT_src_5, SRC_CREATED_BY AS SRC_CREATED_BY_src_5, SRC_MODIFIED_BY AS SRC_MODIFIED_BY_src_5, CREATED_AT AS CREATED_AT_src_5, MODIFIED_AT AS MODIFIED_AT_src_5, SOURCE_SYSTEM_ID AS SOURCE_SYSTEM_ID_src_5 FROM SF_BIGHAMMER.SILVER.DIM_CRM_EXPENSE_TYPES
    ),
    join_watermark_and_source_systems AS (
        SELECT * FROM RAW_ORACLE_CHARGE_PROGRAM_CDC left JOIN TEST_WATERMARK ON TABLE_NAME_src_3 = 'dim_charge_programs' inner JOIN SOURCE_SYSTEMS ON SOURCE_SYSTEM_NAME_src_2 = 'oracle'
    ),
    filter_cdc_operation AS (
        SELECT * FROM join_watermark_and_source_systems WHERE CDC_OPERATION_src_1 IN ('I', 'U') AND MODIFIED_DATE_src_1 >= COALESCE(LAST_LOAD_TIMESTAMP_src_3, '1901-01-01 00:00:00')
    ),
    join_fct_orders AS (
        SELECT * FROM filter_cdc_operation left JOIN FCT_ORDERS_CUST_SS ON 1 = 1
    ),
    join_dim_crm_expense_types AS (
        SELECT * FROM join_fct_orders left JOIN DIM_CRM_EXPENSE_TYPES ON CAST(FREQUENCY_src_1 AS NUMBER) = EXPENSE_TYPE_ID_src_5
    ),
    DIM_ORACLE_PROGRAMS_rename AS (
        SELECT PROGRAM_ID_src_1 AS PROGRAM_ID, COMPANY_ID_src_1 AS COMPANY_ID, PROGRAM_NAME_src_1 AS PROGRAM_NAME, PROGRAM_DESCRIPTION_src_1 AS PROGRAM_DESCRIPTION, TRANSACTION_TYPE_src_1 AS TRANSACTION_TYPE_CODE, FREQUENCY_src_1 AS FREQUENCY, DOC_TYPE_src_1 AS DOC_TYPE_CODE, EXACT_AMOUNT_src_1 AS EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_src_1 AS SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID_src_2 AS SOURCE_SYSTEM_ID, CREATED_DATE_src_1 AS SRC_CREATED_AT, MODIFIED_DATE_src_1 AS SRC_MODIFIED_AT, CREATED_BY_src_1 AS SRC_CREATED_BY, MODIFIED_BY_src_1 AS SRC_MODIFIED_BY, CURRENT_TIMESTAMP() AS CREATED_AT, CURRENT_TIMESTAMP() AS MODIFIED_AT, SOURCE_SYSTEM_NAME_src_2, EXPENSE_TYPE_DESCRIPTION_src_5 FROM join_dim_crm_expense_types
    ),
    DIM_ORACLE_PROGRAMS_final AS (
        SELECT PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, EXPENSE_TYPE_DESCRIPTION_src_5 AS FREQUENCY_DESCRIPTION, 'SYS_NAME' AS SOURCE_SYSTEM_NAME FROM DIM_ORACLE_PROGRAMS_rename
    )
    SELECT PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, FREQUENCY_DESCRIPTION, SOURCE_SYSTEM_NAME FROM DIM_ORACLE_PROGRAMS_final
    ) AS source
    ON target.PROGRAM_ID = source.PROGRAM_ID
    WHEN MATCHED THEN UPDATE SET target.COMPANY_ID = source.COMPANY_ID, target.PROGRAM_NAME = source.PROGRAM_NAME, target.PROGRAM_DESCRIPTION = source.PROGRAM_DESCRIPTION, target.TRANSACTION_TYPE_CODE = source.TRANSACTION_TYPE_CODE, target.FREQUENCY = source.FREQUENCY, target.DOC_TYPE_CODE = source.DOC_TYPE_CODE, target.EXACT_AMOUNT_FLAG = source.EXACT_AMOUNT_FLAG, target.SCHEDULE_VALIDATION_FLAG = source.SCHEDULE_VALIDATION_FLAG, target.SOURCE_SYSTEM_ID = source.SOURCE_SYSTEM_ID, target.SRC_CREATED_AT = source.SRC_CREATED_AT, target.SRC_MODIFIED_AT = source.SRC_MODIFIED_AT, target.SRC_CREATED_BY = source.SRC_CREATED_BY, target.SRC_MODIFIED_BY = source.SRC_MODIFIED_BY, target.MODIFIED_AT = source.MODIFIED_AT, target.FREQUENCY_DESCRIPTION = source.FREQUENCY_DESCRIPTION, target.SOURCE_SYSTEM_NAME = source.SOURCE_SYSTEM_NAME
    WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, COMPANY_ID, PROGRAM_NAME, PROGRAM_DESCRIPTION, TRANSACTION_TYPE_CODE, FREQUENCY, DOC_TYPE_CODE, EXACT_AMOUNT_FLAG, SCHEDULE_VALIDATION_FLAG, SOURCE_SYSTEM_ID, SRC_CREATED_AT, SRC_MODIFIED_AT, SRC_CREATED_BY, SRC_MODIFIED_BY, CREATED_AT, MODIFIED_AT, FREQUENCY_DESCRIPTION, SOURCE_SYSTEM_NAME) VALUES (source.PROGRAM_ID, source.COMPANY_ID, source.PROGRAM_NAME, source.PROGRAM_DESCRIPTION, source.TRANSACTION_TYPE_CODE, source.FREQUENCY, source.DOC_TYPE_CODE, source.EXACT_AMOUNT_FLAG, source.SCHEDULE_VALIDATION_FLAG, source.SOURCE_SYSTEM_ID, source.SRC_CREATED_AT, source.SRC_MODIFIED_AT, source.SRC_CREATED_BY, source.SRC_MODIFIED_BY, source.CREATED_AT, source.MODIFIED_AT, source.FREQUENCY_DESCRIPTION, source.SOURCE_SYSTEM_NAME);

    COMMIT;

    RETURN 'Success';
EXCEPTION
  WHEN OTHER THEN
    ROLLBACK;
    RAISE;
END
$$;